def transform(grid):
    """Complete horizontal mirror symmetry, marking newly added cells with 2."""
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for r in grid for x in r))
    fg = {v for row in grid for v in row if v != bg}
    if not fg:
        return out
    cols = [c for r, row in enumerate(grid) for c, v in enumerate(row) if v != bg]
    left, right = min(cols), max(cols)
    for r, row in enumerate(grid):
        for c in range(left, right + 1):
            mc = left + right - c
            if row[c] != bg and row[mc] == bg:
                out[r][mc] = 2
            elif row[c] == bg and row[mc] != bg:
                out[r][c] = 2
    return out
