def transform(grid):
    """Draw the foreground bounding-box border; rows with multiple marks become solid between them."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, c in points); r1 = max(r for r, c in points)
    c0 = min(c for r, c in points); c1 = max(c for r, c in points)
    out = [row[:] for row in grid]
    # Complete the rectangular outline of the marked object's bounding box.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1)) and grid[r][c] == bg:
                out[r][c] = 2
    # Any row containing at least two original marks forms a solid horizontal bar.
    for r in range(r0, r1 + 1):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
